  "s34.feat.1": { en: "Flagship 34 × 34 mm square MOVs, epoxy encapsulated, for SPD manufacturers and OEMs", zh: "旗舰系列：34 × 34 mm 方形环氧包封 MOV，面向 SPD 制造商与 OEM" },
  "s34.feat.2": { en: "31 UL-recognized model grades — varistor voltage from 82 V to 1,800 V", zh: "31 个 UL 认可型号等级，压敏电压 82 V 至 1,800 V" },
  "s34.feat.3": { en: "UL 1449 Recognized, File E335803 (VZCA2 US / VZCA8 Canada)", zh: "UL 1449 认可，档案号 E335803（美国 VZCA2 / 加拿大 VZCA8）" },
  "s34.feat.4": { en: "In 20 kA, Imax up to 60 kA (8/20 µs); high-energy 10/350 µs and multi-chip parallel ranges", zh: "In 20 kA、Imax 最高 60 kA（8/20 µs）；另有 10/350 µs 高能量与多片并联系列" },
  "s34.feat.5": { en: "Centre melt-through design: the puncture point sits under the copper electrode, so a mating thermal disconnector trips faster", zh: "中心熔穿设计：熔穿点位于铜电极之下，配合热脱离器更快动作" },
  "s34.feat.6": { en: "Eight encapsulated forms — tab, leaded and bare-disc variants for SPD assembly", zh: "八种包封形式——端子、引线与裸片，适配 SPD 组装" },
