  "cert.cov.27l": { en: "23 model grades, varistor voltages 82–820 V (codes 820 and 101–821)", zh: "23 个型号，压敏电压 82–820 V（代码 820 与 101–821）" },
  "cert.cov.54l": { en: "One DC model recognized: 54LK911 (varistor voltage 910 V, DC-rated). No AC models are covered.", zh: "一个 DC 型号在册：54LK911（压敏电压 910 V，DC 额定）。无交流型号被覆盖。" },
  "sp.s34.mc.h2": { en: "34S multi-chip parallel ratings", zh: "34S 多芯片并联参数" },
  "sp.s34.mc.intro": { en: "For higher surge-current and energy ratings in the same 34 mm class, 34S chips are also built as multi-chip parallel assemblies. The catalog lists four configurations — asymmetric and symmetric parallel structures, each in D-suffix and T-suffix models — rated up to In 60 kA and Imax 100 kA (8/20 µs). Column definitions are the same as the standard table above.", zh: "为在同一 34 mm 等级下获得更高的通流与能量等级，34S 芯片还制成多芯片并联结构。手册列出四种结构——不对称与对称并联，各有 D 后缀与 T 后缀型号——标称放电电流最高 60 kA、最大放电电流最高 100 kA（8/20 µs）。列定义与上方常规表相同。" },
  "sp.s34.mc.a.h3": { en: "Asymmetric parallel — D-suffix models (In 30 kA, Imax 65 kA)", zh: "不对称并联结构 — D 后缀型号（In 30 kA、Imax 65 kA）" },
  "sp.s34.mc.b.h3": { en: "Asymmetric parallel — T-suffix models (In 50 kA, Imax 80 kA)", zh: "不对称并联结构 — T 后缀型号（In 50 kA、Imax 80 kA）" },
  "sp.s34.mc.c.h3": { en: "Symmetric parallel — D-suffix models (In 40 kA, Imax 80 kA)", zh: "对称并联结构 — D 后缀型号（In 40 kA、Imax 80 kA）" },
  "sp.s34.mc.d.h3": { en: "Symmetric parallel — T-suffix models (In 60 kA, Imax 100 kA)", zh: "对称并联结构 — T 后缀型号（In 60 kA、Imax 100 kA）" },
  "sp.s34.mc.note": { en: "The multi-chip parallel configurations carry no UL, C-UL or TÜV marks in the catalog tables. For series not yet UL recognized, we can pursue UL certification for your program.", zh: "以上多芯片并联结构在手册参数表中无 UL、C-UL、TÜV 认证标记。对于尚未获得 UL 认可的产品，我们可以为您的项目申请 UL 认证。" },
  "spd.breadcrumb": { en: "ULTIMA Board-Mounted SPD", zh: "ULTIMA 板载 SPD" },
  "spd.pagetitle": { en: "ULTIMA Board-Mounted SPD Modules", zh: "ULTIMA 板载浪涌保护模块" },
  "spd.pagedesc": { en: "Board-mounted surge protective modules in three discharge classes — In 10 / 20 / 40 kA — built on our own MOV chips, with a patented thermal disconnector and remote alarm contact. Supplied for OEM integration.", zh: "三个放电等级的板载浪涌保护模块——In 10 / 20 / 40 kA——采用自产 MOV 芯片，带专利热脱离器与远程报警触点，供 OEM 集成。" },
  "spd.intro.h2": { en: "Board-mounted SPD modules for OEM integration", zh: "供 OEM 集成的板载浪涌保护模块" },
  "spd.intro": { en: "The ULTIMA series is a family of surge protective modules that mount directly on the equipment's printed circuit board — no DIN rail, no separate housing. Each module combines our own metal oxide varistor chips with a built-in thermal disconnector and an alarm contact for remote status signaling, in a compact flame-retardant housing that solders or plugs onto the board. The modules are made by Guiyang High-Tech Yige Electronic Co., Ltd. and supplied to equipment manufacturers for integration into their own products; in North America they are supported by Flyboat Electronic LLC, the factory's sales and engineering center in Bellevue, WA.", zh: "ULTIMA 系列是直接安装在设备印刷电路板上的浪涌保护模块——不用导轨、不用单独外壳。每个模块将自产金属氧化物压敏电阻芯片、内置热脱离器和远程状态信号报警触点集成在紧凑的阻燃外壳内，以焊接或插脚方式装到电路板上。模块由贵阳高新益舸电子有限公司制造，供设备厂商集成到自己的产品中；北美由工厂的销售与工程中心 Flyboat Electronic LLC（华盛顿州贝尔维尤）提供支持。" },
  "spd.design.h2": { en: "Design: the disconnector works from the center of the chip", zh: "设计：脱离器从芯片中心动作" },
  "spd.design": { en: "The ULTIMA disconnector is built around the puncture-point control of our MOV chips. Because each chip's melt-through point is held in the center of the disc, a sliding thermal disconnector seated at that center point responds quickly and consistently when the varistor degrades — separating the chip from the circuit before it can overheat. The design is protected by invention patent ZL201410061277.5. A status window on the module shows the operating state, and a built-in microswitch provides a floating alarm contact (C / NO / NC) for remote signaling.", zh: "ULTIMA 脱离器围绕我们 MOV 芯片的熔穿点控制来设计。由于每片芯片的熔穿点被控制在圆片中心，位于该中心点的滑块式热脱离器在压敏电阻劣化时能快速、一致地动作——在芯片过热之前将其与电路分离。该设计受发明专利 ZL201410061277.5 保护。模块上的状态窗口显示工作状态，内置微动开关提供浮动报警触点（C / NO / NC）用于远程信号。" },
  "spd.fig.pair": { en: "The thermal disconnector in its normal state (left) and after tripping (right).", zh: "热脱离器正常状态（左）与脱扣后（右）。" },
  "spd.fig.internal": { en: "Inside the module: MOV chip, slider disconnector and microswitch alarm contact.", zh: "模块内部：MOV 芯片、滑块式脱离器与微动开关报警触点。" },
  "spd.fig.module": { en: "An ULTIMA B20 module (form /11).", zh: "ULTIMA B20 模块（/11 结构）。" },
  "spd.naming.h2": { en: "How to read an ULTIMA type code", zh: "ULTIMA 型号编码怎么读" },
