// i18n Engine
(function() {
  const STORAGE_KEY = 'flyboat-lang';

  function getLang() {
    return localStorage.getItem(STORAGE_KEY) || 'en';
  }

  function setLang(lang) {
    localStorage.setItem(STORAGE_KEY, lang);
  }

  function applyTranslations(lang) {
    // Update all data-i18n elements
    document.querySelectorAll('[data-i18n]').forEach(el => {
      const key = el.getAttribute('data-i18n');
      const t = TRANSLATIONS[key];
      if (t && t[lang] !== undefined) {
        el.innerHTML = t[lang];
      }
    });

    // Update all data-i18n-placeholder elements
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
      const key = el.getAttribute('data-i18n-placeholder');
      const t = TRANSLATIONS[key];
      if (t && t[lang] !== undefined) {
        el.placeholder = t[lang];
      }
    });

    // Update all language-specific images
    document.querySelectorAll('[data-img-en]').forEach(el => {
      el.src = lang === 'zh' ? el.getAttribute('data-img-zh') : el.getAttribute('data-img-en');
    });

    // Update html lang attribute
    document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en';

    // Update toggle button text
    const toggleBtn = document.querySelector('.lang-toggle');
    if (toggleBtn) {
      toggleBtn.textContent = lang === 'en' ? '中文' : 'EN';
      toggleBtn.setAttribute('title', lang === 'en' ? 'Switch to Chinese' : 'Switch to English');
    }
  }

  function toggleLang() {
    const current = getLang();
    const next = current === 'en' ? 'zh' : 'en';
    setLang(next);
    location.reload();
  }

  // Initialize on DOM ready
  document.addEventListener('DOMContentLoaded', function() {
    const lang = getLang();
    applyTranslations(lang);

    // Bind toggle button
    const toggleBtn = document.querySelector('.lang-toggle');
    if (toggleBtn) {
      toggleBtn.addEventListener('click', toggleLang);
    }
  });
})();
